<?php /* $o is already authorized by the caller. */ $items=partnerOrderItems((int)$o['id']);$totals=partnerTotals($o,$items);?>
<section class="b2b-panel"><div class="b2b-title"><div><p class="b2b-kicker">POSLOVNA NARUDŽBA #<?=(int)$o['id']?></p><h1><?=e($o['company'])?></h1></div><span class="b2b-status"><?=e(partnerStatus($o['status']))?></span></div><p><?=e($o['contact_name'])?> · <?=e($o['email'])?> · <?=e($o['phone'])?><br><?=e($o['address'])?>, <?=e($o['city'])?></p><p><strong>Dostava:</strong> <?=e($o['shipping_method'])?> · <?=partnerMoney(cents($o['shipping_cost']))?><br><?=e($o['shipping_terms'])?></p><?php if($o['note']!==''):?><p><strong>Napomena:</strong> <?=nl2br(e($o['note']))?></p><?php endif;?>
<div class="b2b-table-scroll"><table class="b2b-table"><thead><tr><th>Artikal</th><th>Obračun / kom</th><th>Naručeno</th><th>Isporučeno</th><th>Preostalo</th><th>Otkazano</th><th>Vraćeno</th><th>Cijena / ukupno</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><strong><?=e($i['product_name'])?></strong><small><?=e($i['sku'])?></small></td><td><small><?=e(partnerMode($i['pricing_mode']))?> <?=e($i['pricing_rate'])?>%<br>Osnovica: <?=partnerMoney(cents($i['base_price']))?><br>Popust / dodatak: <?=partnerMoney(abs(cents($i['base_price'])-cents($i['unit_price'])))?></small></td><td><?=(int)$i['quantity']?></td><td><?=(int)$i['fulfilled_qty']?></td><td><?=partnerItemOpen($i)?></td><td><?=(int)$i['cancelled_qty']?></td><td><?=(int)$i['returned_qty']?></td><td><strong><?=partnerMoney(cents($i['unit_price']))?></strong><small><?=partnerMoney(cents($i['unit_price'])*(int)$i['quantity'])?></small></td></tr><?php endforeach;?></tbody></table></div>
<div class="b2b-metrics"><div><span>Vrijednost narudžbe s dostavom</span><strong><?=partnerMoney(cents($o['total']))?></strong></div><div><span>Realizovano za plaćanje</span><strong><?=partnerMoney($totals['due'])?></strong></div><div><span>Preostali artikli</span><strong><?=partnerMoney($totals['remaining'])?></strong></div></div><p class="b2b-muted">Realizovano je vrijednost isporučenih artikala umanjena za povrate, uz jednokratnu dostavu nakon prve isporuke. Ovo je pregled narudžbe, a ne račun ili potvrda naplate.</p></section>
<section class="b2b-panel"><h2>Historija realizacije</h2><?php $events=query('SELECT * FROM partner_order_events WHERE order_id=? ORDER BY id DESC',[$o['id']])->fetchAll();if(!$events):?><p>Narudžba je zaprimljena i čeka obradu.</p><?php endif;foreach($events as $event):?><article class="b2b-event"><strong><?=e(partnerEventLabel($event['kind']))?> · <?=e($event['created_at'])?></strong><p><?=nl2br(e($event['note']))?></p><?php if($event['courier']!==''||$event['tracking_number']!==''):?><p>Kurir: <?=e($event['courier'])?> · Broj pošiljke: <?=e($event['tracking_number'])?></p><?php endif;foreach(query('SELECT i.product_name,e.quantity FROM partner_event_items e JOIN partner_order_items i ON i.id=e.item_id WHERE event_id=?',[$event['id']])->fetchAll() as $line):?><p><?=e($line['product_name'])?> — <?=(int)$line['quantity']?> kom.</p><?php endforeach;?></article><?php endforeach;?></section>
